inline std::string command_config(){nlohmann::json a=nlohmann::json::array();for(const auto& b:ssc_commands::router.bindings)a.push_back({{"name",b.name},{"action",b.action}});return nlohmann::json({{"prefix",std::string(1,ssc_commands::router.prefix)},{"bindings",a}}).dump(2);}
inline bool import_commands(const std::string& bytes){if(bytes.size()>8192)return false;try{auto j=nlohmann::json::parse(bytes);auto next=ssc_commands::router;auto prefix=j.at("prefix").get<std::string>();if(prefix.size()!=1||!j.at("bindings").is_array()||j.at("bindings").size()>32)return false;next.prefix=prefix[0];next.bindings.clear();for(const auto& b:j.at("bindings"))next.bindings.push_back({b.at("name").get<std::string>(),b.at("action").get<std::string>()});if(!next.valid())return false;for(const auto& b:next.bindings){const std::string allowed="|team|all|help|summary|record|kos|tts|mute|unmute|volume|";if(allowed.find("|"+b.action+"|")==std::string::npos)return false;}ssc_commands::router=std::move(next);return true;}catch(...){return false;}}
inline bool save(const std::filesystem::path& dir){
 nlohmann::json j={{"schema",1},{"slash_commands_version",1},{"loading_tips",ssc_loading_tips::enabled.load()},{"random_drafts_enabled",ssc_challenge::random.enabled},{"random_stims",ssc_challenge::random.stims},{"blind_drafts",ssc_challenge::random.blind},{"chaos_effects",ssc_challenge::chaos.effects},{"chaos_controls_shuffle",ssc_challenge::chaos.scramble_controls},{"chaos_controls_interval_ms",ssc_challenge::chaos.control_interval_ms},{"kos_enabled",ssc_kos::enabled},{"kos_color",ssc_kos::color_rgb},{"command_sender",ssc_commands::sender_name},{"commands_enabled",ssc_commands::router.enabled},{"commands",nlohmann::json::parse(command_config())},{"tts_enabled",ssc_chat_tts::settings.enabled},{"tts_announcements",ssc_chat_tts::settings.system},{"tts_own",ssc_chat_tts::settings.own},{"tts_names",ssc_chat_tts::settings.read_names},{"tts_voice",ssc_chat_tts::voice_choice},{"tts_backend",ssc_chat_tts::backend},{"tts_piper_voice",ssc_chat_tts::piper_voice},{"tts_piper_speaker",ssc_chat_tts::piper_speaker},{"tts_volume",ssc_chat_tts::volume},{"tts_speed_percent",ssc_chat_tts::speed_percent}};
 auto path=dir/L"planned-modules.json",temp=dir/L"planned-modules.json.tmp";std::ofstream f(temp,std::ios::binary);f<<j.dump(2);f.close();return bool(f)&&MoveFileExW(temp.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH);
}
inline void load(const std::filesystem::path& dir){ssc_kos::load(dir);ssc_piper::assets().configure(dir);ssc_piper::assets().refresh();auto path=dir/L"planned-modules.json";std::error_code e;if(!std::filesystem::exists(path,e)||std::filesystem::file_size(path,e)>16384||e)return;try{std::ifstream f(path,std::ios::binary);auto j=nlohmann::json::parse(f);if(j.at("schema")!=1)return;ssc_loading_tips::enabled=j.value("loading_tips",true);ssc_challenge::random.enabled=j.value("random_drafts_enabled",false);ssc_challenge::status=ssc_challenge::random.enabled?L"Waiting for a round":L"Off";ssc_challenge::random.stims=j.value("random_stims",true);ssc_challenge::random.blind=j.value("blind_drafts",false);std::array<bool,9> effects{};if(j.contains("chaos_effects")){const auto& a=j.at("chaos_effects");if(!a.is_array()||a.size()>effects.size())return;for(size_t i=0;i<a.size();++i){if(!a[i].is_boolean())return;effects[i]=a[i].get<bool>();}}ssc_challenge::chaos.effects=effects;ssc_challenge::chaos.scramble_controls=false;ssc_challenge::chaos.control_interval_ms=60000;import_commands(j.at("commands").dump());if(j.value("slash_commands_version",0)<1&&ssc_commands::router.prefix=='!')ssc_commands::router.prefix='/';ssc_kos::enabled=j.value("kos_enabled",false);ssc_kos::color_rgb=j.value("kos_color",0xff4545u)&0xffffffu;auto sender=j.value("command_sender",std::string("JARVIS"));if(ssc_kos::valid_text(sender,32))ssc_commands::sender_name=sender;ssc_commands::router.enabled=j.value("commands_enabled",false);ssc_chat_tts::settings.enabled=j.value("tts_enabled",false);ssc_chat_tts::settings.system=j.value("tts_announcements",false);ssc_chat_tts::settings.own=j.value("tts_own",false);ssc_chat_tts::settings.read_names=j.value("tts_names",false);ssc_chat_tts::voice_choice=std::clamp(j.value("tts_voice",0),0,63);ssc_chat_tts::backend=std::clamp(j.value("tts_backend",0),0,1);auto piper=j.value("tts_piper_voice",std::string("norman"));if(ssc_piper::identifier(piper))ssc_chat_tts::piper_voice=piper;ssc_chat_tts::piper_speaker=std::clamp(j.value("tts_piper_speaker",0),0,2047);ssc_chat_tts::volume=std::clamp(j.value("tts_volume",80),0,200);ssc_chat_tts::speed_percent=std::clamp(j.value("tts_speed_percent",ssc_chat_tts::legacy_speed_percent(j.value("tts_rate",0))),50,200);}catch(...){}}
